<script lang="ts">
	import Icon from '../components/Icon.svelte';
	import { getContext, type Component, type Snippet } from 'svelte';
	import type { LutraForm } from './types.js';

    /**
     * @description
     * A polymorphic form button that renders as a `<button>` or `<a>` depending on whether `href` is set.
     * Automatically disables itself while its parent form is in a loading state.
     * Inherits the alignment context set by a parent `FormActions` component.
     *
     * @example
     * <Button type="submit" kind="default">Save</Button>
     * <Button href="/cancel" kind="secondary">Cancel</Button>
     * <Button kind="warn" icon={TrashIcon}>Delete</Button>
     */
    let {
        href,
        type = 'button',
        class: className,
        scale = 'md',
        kind = 'default',
        disabled = false,
        icon,
        onclick,
        children,
    }: {
        /** When set, renders as an `<a>` link instead of a `<button>`. */
        href?: string;
        /** The button type attribute. */
        type?: 'button' | 'submit' | 'reset';
        /** Visual style variant. */
        kind?: 'default' | 'outlined' | 'secondary' | 'warn';
        /** Size variant. */
        scale?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
        /** Additional CSS class names. */
        class?: string;
        /** Whether the button is disabled. Also disabled automatically when the parent form is loading. */
        disabled?: boolean;
        /** Icon component or string to render before the label. */
        icon?: string | Component;
        /** Click event handler. */
        onclick?: (event: MouseEvent) => void;
        /** Button label content. */
        children: Snippet;
    } = $props();

    const form = getContext<LutraForm<any>>('form');
    const align = getContext('form.actions.align');

</script>

{#if href}
    <a class="Button Link button {scale} {kind} {className} {align}" {href} {onclick}>
        {#if icon}
            <Icon {icon} />
        {/if}
        {@render children()}
    </a>
{:else}
    <button class="Button button {scale} {kind} {className} {align}" type={type} disabled={disabled || form?.state === 'loading'} {onclick}>
        {#if icon}
            <Icon {icon} />
        {/if}
        {@render children()}
    </button>
{/if}

<style>
    .Button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
    }
    .Button.full {
        width: 100%;
    }
</style>